def migrate_existing_data(apps, schema_editor):
    """既存のデータを、担当機関の対応表と公開状態に移す。

    - 今ある能力バッジは、今までどおりポータルに出ていたので「公開」にする（公開した日時は分からないので空のまま）。
    - バッジに、今の発行機関の名前と URL を issuer.name / issuer.url として残す。
    - 今ある発行機関は、それぞれ1つのバッジ発行機関にし、今の名前と URL を最初の対応にする。
    """
    Issuer = apps.get_model("chiloportal", "Issuer")
    IssuerMapping = apps.get_model("chiloportal", "IssuerMapping")
    WisdomBadges = apps.get_model("chiloportal", "WisdomBadges")
    KnowledgeBadges = apps.get_model("chiloportal", "KnowledgeBadges")

    WisdomBadges.objects.update(status="published")
    for model in (WisdomBadges, KnowledgeBadges):
        for badge in model.objects.filter(issuer__isnull=False).select_related("issuer"):
            badge.issuer_name = badge.issuer.name
            badge.issuer_url = badge.issuer.url
            badge.save(update_fields=["issuer_name", "issuer_url"])
    for issuer in Issuer.objects.all():
        IssuerMapping.objects.get_or_create(
            issuer_name=issuer.name or "",
            issuer_url=issuer.url or "",
            defaults={"issuer": issuer},
        )


